SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'ozongeneratoren', 'Ozongeneratoren (je Erzeuger Ozonleistung kg/h, Spannung, Frequenz)', 'json', NULL, false, '§4.3.3.2', 'Plan 3: Zeilen je Ozonerzeuger; Σ Ozonleistung → ozon_kapazitaet_sum (M205-17-D4); Abgleich mit ozonbedarf_kg_h ist STAGED (m205-G-11). Anlagen über 1 kg/h: ca. 10 kV, ca. 600 Hz (Orientierung); die Einzelskalare ozongenerator_spannung / _frequenz sind Ablösekandidaten (m205-D-3).', 'imported_unverified', 'Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'register', '{"title":"Ozongeneratoren","subtitle":"§4.3.3.2 — je Erzeuger Ozonleistung, Spannung, Frequenz","add_label":"+ Generator","placement":"section","columns":[{"key":"label","label":"Generator","type":"text","required":true},{"key":"kapazitaet_kg_h","label":"Ozonleistung","type":"number","unit":"kg/h","required":true,"min":0},{"key":"spannung_kv","label":"Spannung","type":"number","unit":"kV","min":0},{"key":"frequenz_hz","label":"Frequenz","type":"number","unit":"Hz","min":0}],"footer":["ozon_kapazitaet_sum"],"note":"Anlagen für Ozonleistungen über $1 \\mathrm{~kg} / \\mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \\%$ bis $13 \\%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \\mathrm{kWh} / \\mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \\%$ mehr."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ozongeneratoren') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ozon_kapazitaet_sum', 'Installierte Ozonleistung (Σ Generatoren)', 'number', 'kg/h', false, '§4.3.3.2', 'Plan 3: Ausgabe der Gleichung M205-17-D4 (sum_rows über ozongeneratoren.kapazitaet_kg_h).', 'imported_unverified', 'Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ozon_kapazitaet_sum') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ozon_pro_doc_calc', 'Spezifische Ozondosis je DOC (berechnet: Ozonkonzentration / DOC)', 'number', 'mg O3/mg DOC', false, '§4.3.3.3, §4.3.6', 'Plan 3: Ausgabe der Gleichung M205-17-D1 (ozon_konz / doc, DOC aus M205-08); Orientierung 0,5–1 mg O3/mg DOC, Bromatminimierung < 0,8 mg/mg. Das Eingabefeld ozon_pro_doc und EQ-04 bleiben — Umstellung STAGED (m205-R-2).', 'imported_unverified', '- Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC, — Die Ozonung von bromidhaltigem Abwasser kann zur Bildung von Bromat führen, dessen Einleitung in Gewässer aufgrund seiner toxikologischen Eigenschaften grundsätzlich unerwünscht ist. Für Oberflächengewässer bestehen keine spezifischen Qualitätsnormen. Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ozon_pro_doc_calc') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ozonbedarf_kg_h', 'Ozonbedarf (Ozonkonzentration × maximaler Zufluss)', 'number', 'kg/h', false, '§4.3.3.2, §4.3.3.3', 'Plan 3: Ausgabe der Gleichung M205-17-D2 (ozon_konz [mg/l] · durchfluss_max [m³/h] / 1000; durchfluss_max aus M205-08).', 'imported_unverified', '- Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC, — Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ozonbedarf_kg_h') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'o2_bedarf_kg_h', 'Sauerstoffbedarf der Ozonerzeugung (Ozonbedarf × Sauerstoffbedarf je kg Ozon)', 'number', 'kg/h', false, '§4.3.3.2', 'Plan 3: Ausgabe der Gleichung M205-17-D3 (ozonbedarf_kg_h · ozon_pro_o2 — das vorhandene Eingabefeld „Sauerstoffbedarf je kg Ozon“, VR = 10, „etwa 10 kg Sauerstoff“); eine Füllung von ozon_pro_o2 aus S4_3_3_2 ist STAGED (m205-E-4).', 'imported_unverified', 'Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'o2_bedarf_kg_h') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'ct_ecoli_basis', 'ct-Wert für Escherichia coli (Basis, 99 % Reduktion; aus Vorversuchen / DVGW W 225)', 'number', 'mg·min/l', false, '§4.3.2', 'Plan 3: Eingabe des experimentell bestimmten ct-Werts für E. coli; ct_ziel (M205-17-D5) multipliziert ihn für Cryptosporidien-Oozysten mit ca. 500 („um ca. das Fünfhundertfache“).', 'imported_unverified', 'Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). Als besonders resistent gegen Ozon haben sich Protozoen-Dauerformen erwiesen. So übersteigt der $c t$-Wert für CryptosporidienOozysten den für Escherichia coli um ca. das Fünfhundertfache (bezüglich einer Reduktion der Keimzahl um 99 \%). Aufgrund der Reaktion von Ozon auch mit anderen, insbesondere organischen Wasserinhaltsstoffen, sowie der Milieuabhängigkeit ( pH -Wert, Temperatur) der Stabilität des Ozons hängen die erforderlichen Bedingungen von den Verhältnissen des Einzelfalles ab und müssen im Regelfall durch Vorversuche ermittelt werden.', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ct_ecoli_basis') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ct_ziel', 'ct-Zielwert für den Zielorganismus (Cryptosporidien: ca. 500 × E. coli)', 'number', 'mg·min/l', false, '§4.3.2', 'Plan 3: Ausgabe der Gleichung M205-17-D5 — if(ct_wert_zielorganismus == cryptosporidien, ct_ecoli_basis · 500, ct_ecoli_basis); „um ca. das Fünfhundertfache“ (L868) — der Faktor 500 ist der gedruckte Näherungswert; Abgleich ct_wert ≥ ct_ziel ist STAGED (m205-G-12).', 'imported_unverified', 'Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). Als besonders resistent gegen Ozon haben sich Protozoen-Dauerformen erwiesen. So übersteigt der $c t$-Wert für CryptosporidienOozysten den für Escherichia coli um ca. das Fünfhundertfache (bezüglich einer Reduktion der Keimzahl um 99 \%). Aufgrund der Reaktion von Ozon auch mit anderen, insbesondere organischen Wasserinhaltsstoffen, sowie der Milieuabhängigkeit ( pH -Wert, Temperatur) der Stabilität des Ozons hängen die erforderlichen Bedingungen von den Verhältnissen des Einzelfalles ab und müssen im Regelfall durch Vorversuche ermittelt werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ct_ziel') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'spez_energie_ozon_tab', 'Spezifischer Energieverbrauch der Ozonerzeugung nach Einsatzgas (§4.3.3.2)', 'number', 'kWh/kg O3', false, '§4.3.3.2', 'Plan 3: etwa 10 kWh/kg Ozon aus Reinsauerstoff, bei Luft ca. 60 % mehr (16 kWh/kg — Rechenwert aus dem Text, m205-J-3); das Eingabefeld spez_energie_ozon (M205-07 / -19, EQ-05 = 10) bleibt — Umstellung STAGED (m205-R-1 / E-3).', 'imported_unverified', 'Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'lookup_fill', '{"source_label":"§4.3.3.2"}'::jsonb, '{"table_code":"S4_3_3_2","role":"value","keys":[{"column":"einsatzgas","from_symbol":"ozon_einsatzgas"}],"value":"spez_energie_kwh_kg"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'spez_energie_ozon_tab') AND w.code = 'M205-17' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'temperatur_ozonentfernung_min', 'Mindesttemperatur der Restozonentfernung nach §4.3.3.4 (thermisch 350 °C / katalytisch 60 °C)', 'number', '°C', false, '§4.3.3.4', 'Plan 3: aus dem Vernichtungsverfahren gefüllt (locked); CR-26 prüft heute „≥ 350 OR katalytisch“ — Gate temperatur_ozonentfernung ≥ Mindesttemperatur je Verfahren ist STAGED (m205-G-13).', 'imported_unverified', 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.', 'lookup_fill', '{"source_label":"§4.3.3.4"}'::jsonb, '{"table_code":"S4_3_3_4","role":"limit","keys":[{"column":"verbrennung_typ","from_symbol":"verbrennung_typ"}],"value":"temp_min_c"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'temperatur_ozonentfernung_min') AND w.code = 'M205-18' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'temperatur_ozonentfernung_max', 'Höchsttemperatur der katalytischen Restozonentfernung nach §4.3.3.4 (80 °C)', 'number', '°C', false, '§4.3.3.4', 'Plan 3: „katalytisch (bei 60 °C bis 80 °C)“ — obere Grenze; für die thermische Vernichtung ist keine Obergrenze gedruckt (Feld ausgeblendet).', 'imported_unverified', 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.', 'lookup_fill', '{"source_label":"§4.3.3.4"}'::jsonb, '{"table_code":"S4_3_3_4","role":"limit","keys":[{"column":"verbrennung_typ","from_symbol":"verbrennung_typ"}],"value":"temp_max_c"}'::jsonb, 'verbrennung_typ == ''katalytisch''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'temperatur_ozonentfernung_max') AND w.code = 'M205-18' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'verbrennung_haltezeit_min', 'Mindest-Haltezeit der thermischen Restozonentfernung nach §4.3.3.4 (2 s)', 'number', 's', false, '§4.3.3.4', 'Plan 3: „Erhitzen auf 350 °C über mindestens 2 Sekunden“; Gate verbrennung_haltezeit_s ≥ 2 s bei thermischer Vernichtung ist STAGED (m205-G-13).', 'imported_unverified', 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.', 'lookup_fill', '{"source_label":"§4.3.3.4"}'::jsonb, '{"table_code":"S4_3_3_4","role":"limit","keys":[{"column":"verbrennung_typ","from_symbol":"verbrennung_typ"}],"value":"haltezeit_min_s"}'::jsonb, 'verbrennung_typ == ''thermisch''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verbrennung_haltezeit_min') AND w.code = 'M205-18' AND s.code = 'DWA-M-205';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'verbrennung_typ == ''thermisch''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'verbrennung_haltezeit_s' AND w.code = 'M205-18' AND s.code = 'DWA-M-205' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'chlorungsmittel', 'Chlorungsmittel (je Mittel Dosis, Kontaktzeit, Restchlor gegen §4.4.2)', 'json', NULL, false, '§4.4.2', 'Plan 3: Zeilen je eingesetztem Chlorungsmittel mit den gedruckten Bereichen (Chlorgas / Hypochlorit 1–20 mg/l freies Chlor, 15–30 min; Chlordioxid 5–10 g/m³, bei sandfiltriertem Abwasser 1–5 g/m³, wenige Minuten); Zähler → chlordosis_verletzungen (M205-21-D1). Die Einzelskalare bleiben (Ablösung m205-D-5); Umstellung der Gates CR-11/22/23/24 ist STAGED (m205-G-2).', 'imported_unverified', 'Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird. — Chlordioxid muss an Ort und Stelle hergestellt und sofort verbraucht werden, da es in Konzentration über 30 Volumenprozent explosiv ist und die Lösung schnell zerfällt. Dazu stehen mehrere Verfahren zur Verfügung. Beim Chlorit-Chlor-Verfahren wird Chlorwasser mit saurem pHWert ( $<2$ ) mit 10 \%iger Natriumchloritlösung zur Reaktion gebracht. Beim häufiger eingesetzten Chlorit-Salzsäure-Verfahren wird Natriumchlorit mit Salzsäure zu Chlordioxid umgesetzt. Ein weiteres Herstellungsverfahren geht von Natriumchlorit und Natriumperoxodisulfat aus. Da das erzeugte Chlordioxid als Gas nicht beständig ist, muss unmittelbar vor der Anwendung eine wässrige Lösung mit 1 g bis 3 g Chlordioxid pro Liter zubereitet werden. Die Zugabe kann im Durchflussverfahren mit dem Ansaug-Injektorsystem oder über Membranpumpen erfolgen. Die Dosierung erfolgt mengenproportional in Abhängigkeit vom Chlordioxidüberschuss im Wasser und ist von der organischen Belastung des Abwassers und der erforderlichen Keimreduktionsrate abhängig. Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur $1 \mathrm{~g} / \mathrm{m}^{3}$ bis $5 \mathrm{~g} / \mathrm{m}^{3}$. Die erforderliche Einwirkzeit beträgt wenige Minuten.', 'register', '{"title":"Chlorungsmittel","subtitle":"§4.4.2 — je eingesetztem Mittel Dosis, Kontaktzeit und Restchlor gegen die gedruckten Bereiche","add_label":"+ Mittel","placement":"section","columns":[{"key":"mittel","label":"Mittel","type":"enum","options":["chlorgas","natriumhypochlorit","chlordioxid"],"option_labels":{"chlorgas":"Chlorgas (Cl₂)","natriumhypochlorit":"Natriumhypochlorit (NaOCl)","chlordioxid":"Chlordioxid (ClO₂)"},"required":true,"discriminator":true},{"key":"dosis","label":"Dosis","type":"number","required":true,"min":0,"aria_label":"Dosis (mg/l freies Chlor bzw. g/m³ Chlordioxid)"},{"key":"dosis_unit","label":"Einheit","type":"derived","expr":"lookup(''S4_4_2'', mittel, ''dosis_unit'')"},{"key":"dosis_min","label":"Dosis min (§4.4.2)","type":"derived","expr":"lookup(''S4_4_2'', mittel, ''dosis_min'')"},{"key":"dosis_max","label":"Dosis max (§4.4.2)","type":"derived","expr":"lookup(''S4_4_2'', mittel, ''dosis_max'')"},{"key":"sandfiltriert","label":"sandfiltriertes Abwasser (geringe Restverschmutzung)","type":"enum","options":["ja","nein"],"option_labels":{"ja":"ja (1–5 g/m³)","nein":"nein (5–10 g/m³)"},"required":true,"visible_when":"mittel == ''chlordioxid''"},{"key":"dosis_min_eff","label":"Dosis min (gültig)","type":"derived","expr":"if(mittel == ''chlordioxid'', if(sandfiltriert == ''ja'', lookup(''S4_4_2'', mittel, ''dosis_sandfiltriert_min''), dosis_min), dosis_min)"},{"key":"dosis_max_eff","label":"Dosis max (gültig)","type":"derived","expr":"if(mittel == ''chlordioxid'', if(sandfiltriert == ''ja'', lookup(''S4_4_2'', mittel, ''dosis_sandfiltriert_max''), dosis_max), dosis_max)"},{"key":"dosis_ok","label":"Dosis im Bereich","type":"derived","expr":"if(dosis >= dosis_min_eff AND dosis <= dosis_max_eff, 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}},{"key":"kontaktzeit_ist","label":"Kontaktzeit","type":"number","unit":"min","min":0},{"key":"kontaktzeit_text","label":"Kontaktzeit (§4.4.2)","type":"derived","expr":"lookup(''S4_4_2'', mittel, ''kontaktzeit_text'')"},{"key":"restchlor","label":"Restchlor (freies Chlor)","type":"number","unit":"mg/l","min":0,"visible_when":"mittel != ''chlordioxid''"}],"footer":["chlordosis_verletzungen"],"note":"Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird. Chlordioxid muss an Ort und Stelle hergestellt und sofort verbraucht werden, da es in Konzentration über 30 Volumenprozent explosiv ist und die Lösung schnell zerfällt. Dazu stehen mehrere Verfahren zur Verfügung. Beim Chlorit-Chlor-Verfahren wird Chlorwasser mit saurem pHWert ( $<2$ ) mit 10 \\%iger Natriumchloritlösung zur Reaktion gebracht. Beim häufiger eingesetzten Chlorit-Salzsäure-Verfahren wird Natriumchlorit mit Salzsäure zu Chlordioxid umgesetzt. Ein weiteres Herstellungsverfahren geht von Natriumchlorit und Natriumperoxodisulfat aus. Da das erzeugte Chlordioxid als Gas nicht beständig ist, muss unmittelbar vor der Anwendung eine wässrige Lösung mit 1 g bis 3 g Chlordioxid pro Liter zubereitet werden. Die Zugabe kann im Durchflussverfahren mit dem Ansaug-Injektorsystem oder über Membranpumpen erfolgen. Die Dosierung erfolgt mengenproportional in Abhängigkeit vom Chlordioxidüberschuss im Wasser und ist von der organischen Belastung des Abwassers und der erforderlichen Keimreduktionsrate abhängig. Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur $1 \\mathrm{~g} / \\mathrm{m}^{3}$ bis $5 \\mathrm{~g} / \\mathrm{m}^{3}$. Die erforderliche Einwirkzeit beträgt wenige Minuten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'chlorungsmittel') AND w.code = 'M205-21' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'chlordosis_verletzungen', 'Chlorungsmittel mit Dosis außerhalb des §4.4.2-Bereichs (Anzahl)', 'number', NULL, false, '§4.4.2', 'Plan 3: Ausgabe der Gleichung M205-21-D1 (count_rows über chlorungsmittel mit dosis_ok == 0).', 'imported_unverified', 'Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird. — Chlordioxid muss an Ort und Stelle hergestellt und sofort verbraucht werden, da es in Konzentration über 30 Volumenprozent explosiv ist und die Lösung schnell zerfällt. Dazu stehen mehrere Verfahren zur Verfügung. Beim Chlorit-Chlor-Verfahren wird Chlorwasser mit saurem pHWert ( $<2$ ) mit 10 \%iger Natriumchloritlösung zur Reaktion gebracht. Beim häufiger eingesetzten Chlorit-Salzsäure-Verfahren wird Natriumchlorit mit Salzsäure zu Chlordioxid umgesetzt. Ein weiteres Herstellungsverfahren geht von Natriumchlorit und Natriumperoxodisulfat aus. Da das erzeugte Chlordioxid als Gas nicht beständig ist, muss unmittelbar vor der Anwendung eine wässrige Lösung mit 1 g bis 3 g Chlordioxid pro Liter zubereitet werden. Die Zugabe kann im Durchflussverfahren mit dem Ansaug-Injektorsystem oder über Membranpumpen erfolgen. Die Dosierung erfolgt mengenproportional in Abhängigkeit vom Chlordioxidüberschuss im Wasser und ist von der organischen Belastung des Abwassers und der erforderlichen Keimreduktionsrate abhängig. Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur $1 \mathrm{~g} / \mathrm{m}^{3}$ bis $5 \mathrm{~g} / \mathrm{m}^{3}$. Die erforderliche Einwirkzeit beträgt wenige Minuten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'chlordosis_verletzungen') AND w.code = 'M205-21' AND s.code = 'DWA-M-205';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'chlormittel_typ == ''chlordioxid''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'clo2_konzentration' AND w.code = 'M205-21' AND s.code = 'DWA-M-205' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'chlormittel_typ != ''chlordioxid''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'chlor_kontaktzeit' AND w.code = 'M205-21' AND s.code = 'DWA-M-205' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'chlormittel_typ != ''chlordioxid''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'chlor_ph' AND w.code = 'M205-21' AND s.code = 'DWA-M-205' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'chlormittel_typ != ''chlordioxid''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'restchlor_betrieb' AND w.code = 'M205-21' AND s.code = 'DWA-M-205' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'proben_desinfektion', 'Mikrobiologische Proben vor / nach der Desinfektionsstufe (je Probe c_in, c_out → Log-Reduktion)', 'json', NULL, false, '§2.1, §4.1.4.2', 'Plan 3: Zeilen je Probe; Mittel / Minimum der Log-Reduktion → log_reduktion_mean / log_reduktion_min (M205-24-D1 / -D2), Anzahl → proben_count (-D3). Die Perzentil-Einhaltungsregel (Tab. 1 / 2) ist nicht gedruckt (m205-F-1); das Eingabefeld log_reduktion (M205-10 / -25, CR-20) bleibt (m205-G-3).', 'imported_unverified', 'Die Wirksamkeit der Abwasserdesinfektion ist durch den bestimmungsgemäßen Betrieb der eingesetzten Verfahrenstechnik nachzuweisen und am Auslauf der Kläranlage vor der Vermischung mit dem Gewässer zu überprüfen. Zur Bewertung der reduzierenden Wirkung werden die Konzentrationen der Leitorganismen im Zulauf unmittelbar vor sowie nach der Desinfektionsanlage bestimmt (mikrobiologischer Nachweis). Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. Entscheidend für die Bewertung des behandelten Wassers ist jedoch die erreichte Konzentration im Abwasser nach der Behandlung. — Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend.', 'register', '{"title":"Mikrobiologische Proben (Zulauf / Ablauf der Desinfektionsstufe)","subtitle":"§2.1 / §4.1.4.2 — je Probe Datum, Organismus, Konzentration vor und nach der Desinfektion → Log-Reduktion","add_label":"+ Probe","placement":"section","columns":[{"key":"datum","label":"Datum","type":"date","required":true},{"key":"organismus","label":"Leitorganismus","type":"text","required":true,"datalist":["Escherichia coli","Intestinale Enterokokken","Gesamtcoliforme Bakterien","Fäkalcoliforme Bakterien","Fäkalstreptokokken","Salmonellen","Darmviren"]},{"key":"c_in","label":"c vor Desinfektion","type":"number","required":true,"min":0,"aria_label":"Konzentration im Zulauf unmittelbar vor der Desinfektionsanlage"},{"key":"c_out","label":"c nach Desinfektion","type":"number","required":true,"min":0,"aria_label":"Konzentration nach der Desinfektionsanlage"},{"key":"log_red","label":"Log-Reduktion","type":"derived","expr":"log10(c_in / c_out)"},{"key":"limit","label":"Zielwert","type":"number","min":0},{"key":"ok","label":"Zielwert eingehalten","type":"derived","expr":"if(c_out <= limit, 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}}],"footer":["proben_count","log_reduktion_mean","log_reduktion_min"],"note":"Die Wirksamkeit der Abwasserdesinfektion ist durch den bestimmungsgemäßen Betrieb der eingesetzten Verfahrenstechnik nachzuweisen und am Auslauf der Kläranlage vor der Vermischung mit dem Gewässer zu überprüfen. Zur Bewertung der reduzierenden Wirkung werden die Konzentrationen der Leitorganismen im Zulauf unmittelbar vor sowie nach der Desinfektionsanlage bestimmt (mikrobiologischer Nachweis). Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. Entscheidend für die Bewertung des behandelten Wassers ist jedoch die erreichte Konzentration im Abwasser nach der Behandlung. c nach Desinfektion = 0 („nicht nachweisbar“) ist als Log-Reduktion nicht definiert — die Nachweisgrenze eintragen. Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'proben_desinfektion') AND w.code = 'M205-24' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'proben_count', 'Anzahl der mikrobiologischen Proben', 'number', NULL, false, '§4.1.4.2', 'Plan 3: Ausgabe der Gleichung M205-24-D3 (count_rows über proben_desinfektion); monatliche Nachweise sind in der Regel ausreichend.', 'imported_unverified', 'Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'proben_count') AND w.code = 'M205-24' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'log_reduktion_mean', 'Log-Reduktion (Mittel der Proben)', 'number', 'log10', false, '§2.1', 'Plan 3: Ausgabe der Gleichung M205-24-D1 (mean_rows über proben_desinfektion.log_red, Proben mit c_out > 0); die statistische Einhaltungsregel ist Sache der Behörde (§2.1, m205-F-1).', 'imported_unverified', 'Die Wirksamkeit der Abwasserdesinfektion ist durch den bestimmungsgemäßen Betrieb der eingesetzten Verfahrenstechnik nachzuweisen und am Auslauf der Kläranlage vor der Vermischung mit dem Gewässer zu überprüfen. Zur Bewertung der reduzierenden Wirkung werden die Konzentrationen der Leitorganismen im Zulauf unmittelbar vor sowie nach der Desinfektionsanlage bestimmt (mikrobiologischer Nachweis). Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. Entscheidend für die Bewertung des behandelten Wassers ist jedoch die erreichte Konzentration im Abwasser nach der Behandlung.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'log_reduktion_mean') AND w.code = 'M205-24' AND s.code = 'DWA-M-205';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'log_reduktion_min', 'Log-Reduktion (Minimum der Proben)', 'number', 'log10', false, '§2.1', 'Plan 3: Ausgabe der Gleichung M205-24-D2 (min_rows über proben_desinfektion.log_red, Proben mit c_out > 0).', 'imported_unverified', 'Die Wirksamkeit der Abwasserdesinfektion ist durch den bestimmungsgemäßen Betrieb der eingesetzten Verfahrenstechnik nachzuweisen und am Auslauf der Kläranlage vor der Vermischung mit dem Gewässer zu überprüfen. Zur Bewertung der reduzierenden Wirkung werden die Konzentrationen der Leitorganismen im Zulauf unmittelbar vor sowie nach der Desinfektionsanlage bestimmt (mikrobiologischer Nachweis). Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. Entscheidend für die Bewertung des behandelten Wassers ist jedoch die erreichte Konzentration im Abwasser nach der Behandlung.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'log_reduktion_min') AND w.code = 'M205-24' AND s.code = 'DWA-M-205';
COMMIT;
